cd /workspace && python3 -I - <<'PY'
import json,collections
lines=[json.loads(l) for l in open('logs/recorded/events.jsonl') if l.strip()]
by=collections.defaultdict(lambda: collections.Counter())
for d in lines:
    by[d.get('step')][d['kind']+('/'+d['outcome'] if d.get('outcome') else '')]+=1
for s in sorted(by,key=lambda x:(x is None,x)):
    print(s,dict(by[s]))
print()
for d in lines:
    if d['kind']=='relocation': print(json.dumps(d))
print('--- missing reads by step/id ---')
for d in lines:
    if d['kind']=='read' and d['outcome']=='missing': print(d['step'],d['id'],d.get('difficulty'),d.get('index'),d.get('path'))
PY

